  {
    "id": "32_image_library",
    "title": "32. Image Library",
    "category": "General",
    "code": "\n\n//\n// This template displays all of the images and their names.\n// You probably don't want to modify this template directly.\n//\n// You can add an image anywhere by specifying the name of the\n// image in quotes, the coordinates to put the center of the\n// image, and the size (how many units wide or tall; feel free\n// to experiment):\n//\n//     image(\"banana\", [0, 0], 2);\n//\n//\n// Other templates make it easy to change which image is used,\n// so you can just refer to this template to see your choices.\n//\n\nvar rows = ceil(_.keys(imageLibrary).length / 5);\ninit({ range: [[-1, 9], [-(rows * 3) + 1, 1]], scale: 48 });\n_.each(_.keys(imageLibrary), function(imageName, n) {\n    var x = (2 * (n % 5));\n    var y = -3 * floor(n / 5);\n    image(imageName, [x, y], 1.5);\n    label([x, y - 1.3], imageName, \"center\", false);\n});\n\n"
  },
  {
    "id": "33_image",
    "title": "33. Image",
    "category": "General",
    "code": "\n\n//\n// See the \"Image library\" template to see all the possible\n// images.\n//\nvar IMAGE = \"mouse\";\nvar SIZE = 100;\n\nvar PADDING = 4;\n\n/////////////////////////////////////////////////////////\nvar pad = PADDING / SIZE;\ninit({\n    range: [[-1/2 - pad, 1/2 + pad], [-1/2 - pad, 1/2 + pad]],\n    scale: SIZE\n});\nimage(IMAGE, [0, 0], 1);\n\n"
  },
  {
    "id": "34_ten_frame",
    "title": "34. Ten frame",
    "category": "General",
    "code": "\n\n\n//\n// Ten Frame\n// Fill in the colors for each spot or use `null` to\n// leave a spot empty:\nvar TEN_FRAME = [[BLUE_D, BLUE_D, BLUE_D, BLUE_D, BLUE_D],\n                 [BLUE_D, BLUE_D, null, null, null]];\n\n// Set to true to orient the ten frame vertically:\nvar VERTICAL = false;\n\n// Adjust the overall size\nvar SCALE = 50;\n\n////////////////////////////////////////////////////////////\n\nstyle({\n    stroke: GRAY\n});\nif (VERTICAL) {\n    init({ range: [[-0.54, 1.54], [-0.54, 4.54]], scale: SCALE });\n    path([[-0.5, -0.5], [-0.5, 4.5], [1.5, 4.5], [1.5, -0.5], true]);\n    path([[0.5, -0.5], [0.5, 4.5]]);\n    _(4).times(function(n) {\n        path([[-0.5, n + 0.5], [1.5, n + 0.5]]);\n    });\n} else {\n    init({ range: [[-0.54, 4.54], [-0.54, 1.54]], scale: SCALE });\n    path([[-0.5, -0.5], [4.5, -0.5], [4.5, 1.5], [-0.5, 1.5], true]);\n    path([[-0.5, 0.5], [4.5, 0.5]]);\n    _(4).times(function(n) {\n        path([[n + 0.5, -0.5], [n + 0.5, 1.5]]);\n    });\n}\n\n_.each(TEN_FRAME, function(rowColors, row) {\n    _.each(rowColors, function(color, col) {\n        drawCircle({\n           center: VERTICAL ? [row, col] : [col, 1 - row],\n           radius: 0.3,\n           color: color,\n           fillOpacity: 1\n        });\n    });\n});\n\n"
  },
  {
    "id": "35_drawing_helper_functions",
    "title": "35. Drawing helper functions",
    "category": "General",
    "code": "\n\n/* The X and Y ranges of this canvas */\nvar range = [[0.9, 6.1], [0.9, 5.1]];\n\n/* The output's largest side is limited to this many pixels */\nvar size = 320;\n\nsetup();\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n//*******************PUT YOUR CODE BELOW HERE****************//\n\n\n\nrect([1, 1], 5, 2, BLUE_E, 1, BLUE_C, 0.5);\n\npoint([5, 5], \"\", GREEN_D, 1);\n\n\n//*******************PUT YOUR CODE ABOVE HERE****************//\nfunction point(point_xy, label, color, opacity) {\n    drawPoint({\n        point: [point_xy[0], point_xy[1]],\n        label: label,\n        color: color,\n        opacity: opacity\n    });\n}\n\nfunction line(points, color, opacity) {\n    drawLine({\n        points: points,\n        color: color,\n        opacity: opacity\n    });\n}\n\nfunction ray(points, color, opacity) {\n    drawRay({\n    points: points,\n        color: color,\n        opacity: opacity\n    });\n}\n\nfunction ray_angle(point, angle, color, opacity) {\n    drawRay({\n        point: point,\n        angle: angle,\n        color: color,\n        opacity: opacity\n    });\n}\n\nfunction segment(points, color, opacity) {\n    drawSegment({\n        points: points,\n        color: color,\n        opacity: opacity\n    });\n}\n\nfunction rect(lowleft_xy, length, height, stroke, strokeOpacity, fill, fillOpacity) {\n    drawPolygon({\n        points: [\n            [lowleft_xy[0], lowleft_xy[1]],\n            [lowleft_xy[0] + length,lowleft_xy[1]],\n            [lowleft_xy[0] + length,lowleft_xy[1] + height],\n            [lowleft_xy[0], lowleft_xy[1] + height]\n            ],\n        angleLabels: [],\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction rect_rot(lowleft_xy, length, height, angle, stroke, strokeOpacity, fill, fillOpacity) {\n    drawPolygon({\n        points: [\n            [lowleft_xy[0], lowleft_xy[1]],\n            addPoints([lowleft_xy[0], lowleft_xy[1]], polar(length, angle)),\n            addPoints([lowleft_xy[0], lowleft_xy[1]], polar(length, angle), polar(height, 90 + angle)),\n            addPoints([lowleft_xy[0], lowleft_xy[1]], polar(height, 90 + angle)),\n            ],\n        angleLabels: [],\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction etriangle(lowleft_xy, side, stroke, strokeOpacity, fill, fillOpacity) {\n    drawPolygon({\n        points: [\n            [lowleft_xy[0], lowleft_xy[1]],\n            addPoints([lowleft_xy[0], lowleft_xy[1]], polar(side, 60)),\n            [lowleft_xy[0] + side, lowleft_xy[1]]\n            ],\n        angleLabels: [],\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction etriangle_rot(lowleft_xy, side, angle, stroke, strokeOpacity, fill, fillOpacity) {\n    drawPolygon({\n        points: [\n            [lowleft_xy[0], lowleft_xy[1]],\n            addPoints([lowleft_xy[0], lowleft_xy[1]], polar(side, 60 + angle)),\n            addPoints([lowleft_xy[0], lowleft_xy[1]], polar(side, angle)),\n            ],\n        angleLabels: [],\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction reg_polygon(center, radius, sides, stroke, strokeOpacity, fill, fillOpacity) {\n    var int_angle = 2 * PI / sides;\n    var offset = (1 / sides - 0.5) * PI;\n\n    var points = _.times(sides, function(i) {\n        return addPoints(center, polar(radius, toDegrees(i * int_angle + offset)));\n    });\n\n    drawPolygon({\n        points: points,\n        stroke:stroke,\n        strokeOpacity:strokeOpacity,\n        fill:fill,\n        fillOpacity: fillOpacity,\n        angleLabels: []\n    });\n}\n\nfunction reg_polygon_rot(center, radius, sides, angle, stroke, strokeOpacity, fill, fillOpacity) {\n    var int_angle = 2 * PI / sides;\n    var offset = (1 / sides - 0.5 + angle / 180) * PI;\n\n    var points = _.times(sides, function(i) {\n        return addPoints(center,polar(radius, toDegrees(i * int_angle + offset)));\n    });\n\n    drawPolygon({\n        points: points,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity,\n        angleLabels: []\n    });\n}\n\nfunction polygon(points, stroke, strokeOpacity, fill, fillOpacity) {\n    drawPolygon({\n        points: points,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity,\n        angleLabels: []\n    });\n}\n\nfunction circ(center_xy, radius, stroke, strokeOpacity, fill, fillOpacity) {\n    drawCircle({\n        center: [center_xy[0],center_xy[1]],\n        radius: radius,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\n\nfunction ellipse(center_xy, radius_x, radius_y, stroke, strokeOpacity, fill, fillOpacity) {\n    drawEllipse({\n        center: [center_xy[0], center_xy[1]],\n        radii: [radius_x, radius_y],\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction arc(center_xy, radius, degree_start, degree_end, stroke, strokeOpacity, fill, fillOpacity) {\n    drawArc({\n        center: center_xy,\n        radius: radius,\n        start: degree_start,\n        end: degree_end,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction elliptical_arc(center_xy, radius_x, radius_y, degree_start, degree_end, stroke, strokeOpacity, fill, fillOpacity) {\n    drawArc({\n        center: center_xy,\n        radii: [radius_x, radius_y],\n        start: degree_start,\n        end: degree_end,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction sector(center_xy, radius, degree_start, degree_end, stroke, strokeOpacity, fill, fillOpacity) {\n    drawSector({\n        center: center_xy,\n        radius: radius,\n        start: degree_start,\n        end: degree_end,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\nfunction elliptical_sector(center_xy, radius_x, radius_y, degree_start, degree_end, stroke, strokeOpacity, fill, fillOpacity) {\n    drawSector({\n        center: center_xy,\n        radii: [radius_x, radius_y],\n        start: degree_start,\n        end: degree_end,\n        stroke: stroke,\n        strokeOpacity: strokeOpacity,\n        fill: fill,\n        fillOpacity: fillOpacity\n    });\n}\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\nfunction setup() {\n    var scales = _.map(range, function(extent) {\n        return Perseus.Util.scaleFromExtent(extent, size);\n    });\n    init({range: range, scale: _.min(scales)});\n}\n\n\n"
  },
  {
    "id": "36_five_frame",
    "title": "36. Five frame",
    "category": "General",
    "code": "\n\n\n//\n// Five Frame\n// Fill in the colors for each spot or use `null` to\n// leave a spot empty:\nvar FIVE_FRAME = [[null, BLUE_D, null, BLUE_D, BLUE_D]];\n\n// Set to true to orient the ten frame vertically:\nvar VERTICAL = false;\n\n// Adjust the overall size\nvar SCALE = 50;\n\n////////////////////////////////////////////////////////////\n\nstyle({\n    stroke: GRAY\n});\nif (VERTICAL) {\n    init({ range: [[-0.54, 0.54], [-0.54, 4.54]], scale: SCALE });\n    path([[-0.5, -0.5], [-0.5, 4.5], [0.5, 4.5], [0.5, -0.5], true]);\n    path([[0.5, -0.5], [0.5, 4.5]]);\n    _(4).times(function(n) {\n        path([[-0.5, n + 0.5], [0.5, n + 0.5]]);\n    });\n} else {\n    init({ range: [[-0.54, 4.54], [-0.54, 0.54]], scale: SCALE });\n    path([[-0.5, -0.5], [4.5, -0.5], [4.5, 0.5], [-0.5, 0.5], true]);\n    path([[-0.5, 0.5], [4.5, 0.5]]);\n    _(4).times(function(n) {\n        path([[n + 0.5, -0.5], [n + 0.5, 0.5]]);\n    });\n}\n\n_.each(FIVE_FRAME, function(rowColors, row) {\n    _.each(rowColors, function(color, col) {\n        drawCircle({\n           center: VERTICAL ? [0, col] : [col, 0],\n           radius: 0.3,\n           color: color,\n           fillOpacity: 1\n        });\n    });\n});\n\n"
  },
  {
    "id": "37_shade_area_under_curve",
    "title": "37. Shade area under curve",
    "category": "General",
    "code": "// X and Y ranges of the graph\nvar X_RANGE = [-10, 10];\nvar Y_RANGE = [-10, 10];\n\n// var STEP = [<x tick step>, <y tick step>];\n// var STEP = [10, 25];\nvar STEP = \"auto\";\n\n// Width of the graph in pixels\n// Let's use 320 for \"normal\" graphs and 170 for \"small\" graphs.\n// If this is for the background of a widget (transformer, interactive graph, etc), use 400.\nvar SIZE = 320;\n\nvar xScale;\nvar yScale;\nsetup();\n//////////////////////////////////////////////////////////////\n\n\n\nstyle({\n    stroke: BLUE_D,\n    fill: \"none\",\n    strokeWidth: 3\n});\n\nplot(function(x) {\n    // Function to shade under\n    return 0.03 * (x+5)*(x+2)*(x-3)*(x-6);\n}, [-4, 2], // <-- x-range to shade\n    false, true, { stroke: \"none\", fill: BLUE_D, fillOpacity: 0.3 }\n);\n\nplot(function(x) {\n    // Plot the entire function\n    return 0.03 * (x+5)*(x+2)*(x-3)*(x-6);\n}, X_RANGE);\n\n\n//////////////////////////////////////////////////////////////\n// Setup grid, ticks, and labels and initialize graph.\nfunction setup() {\n    var dimensions = [SIZE, SIZE];\n    var range = [X_RANGE, Y_RANGE];\n    var step = STEP;\n    if (step === \"auto\") {\n        step = _.map(range, function(extent, i) {\n            return Perseus.Util.tickStepFromExtent(\n                    extent, dimensions[i]);\n        });\n    }\n    var gridConfig = _.map(range, function(extent, i) {\n        return Perseus.Util.gridDimensionConfig(\n                step[i],\n                extent,\n                dimensions[i]);\n    });\n    var scale = _.pluck(gridConfig, \"scale\");\n    xScale = scale[0];\n    yScale = scale[1];\n    var paddedRange = _.map(range, function(extent, i) {\n        var padding = 25 / scale[i];\n        return [extent[0], extent[1] + padding];\n    });\n    graphInit({\n        gridRange: range,\n        range: paddedRange,\n        scale: scale,\n        axisArrows: \"<->\",\n        labelFormat: function(s) {\n            return \"\\\\small{\" + s + \"}\";\n        },\n        gridStep: _.pluck(gridConfig, \"gridStep\"),\n        tickStep: _.pluck(gridConfig, \"tickStep\"),\n        labelStep: 1,\n        unityLabels: _.pluck(gridConfig, \"unityLabel\")\n    });\n    style({\n        clipRect: [[X_RANGE[0], Y_RANGE[0]],\n                [X_RANGE[1] - X_RANGE[0],\n                Y_RANGE[1] - Y_RANGE[0]]]\n    });\n\n    label([0, Y_RANGE[1]], \"y\", \"above\");\n    label([X_RANGE[1], 0], \"x\", \"right\");\n}\n\n"
  },
  {
    "id": "38_riemann_sums",
    "title": "38. Riemann sums",
    "category": "General",
    "code": "// X and Y ranges of the graph\nvar X_RANGE = [-10, 10];\nvar Y_RANGE = [-10, 10];\n\n// var STEP = [<x tick step>, <y tick step>];\n// var STEP = [10, 25];\nvar STEP = \"auto\";\n\n// Width of the graph in pixels\n// Let's use 320 for \"normal\" graphs and 170 for \"small\" graphs.\n// If this is for the background of a widget (transformer, interactive graph, etc), use 400.\nvar SIZE = 320;\n\nvar xScale;\nvar yScale;\nsetup();\n//////////////////////////////////////////////////////////////\n\n\n\nriemann(\n    function(x) {\n        // function\n        return 0.03*(x+5)*(x+2)*(x-3)*(x-6);\n    },\n    [-5, 3],  // x-range to shade\n    8,        // number of divisions\n    \"center\",   // left, right, or center\n    BLUE_D      // color\n);\n\nstyle({\n    stroke: BLUE_D,\n    fill: \"none\",\n    strokeWidth: 3\n});\n\nplot(function(x) {\n    // Plot the entire function\n    return 0.03*(x+5)*(x+2)*(x-3)*(x-6);\n}, X_RANGE);\n\n//////////////////////////////////////////////////////////////\nfunction riemann(fn, domain, divisions, kind, color) {\n    var x = domain[0];\n    var step = (domain[1] - domain[0]) / divisions;\n    var offset = kind === \"left\" ? 0 : kind === \"center\" ? step / 2 : step;\n    while (x < domain[1]) {\n        style({\n            fill: color,\n            stroke: color,\n            opacity: 0.3\n        });\n        path([[x, 0], [x, fn(x + offset)], [x + step, fn(x + offset)], [x + step, 0], true]);\n        \n        style({\n            fill: \"none\",\n            stroke: color,\n            strokeWidth: 1,\n            opacity: 1\n        });\n        path([[x, 0], [x, fn(x + offset)], [x + step, fn(x + offset)], [x + step, 0], true]);\n        x += step;\n    }\n}\n\n\n//////////////////////////////////////////////////////////////\n// Setup grid, ticks, and labels and initialize graph.\nfunction setup() {\n    var dimensions = [SIZE, SIZE];\n    var range = [X_RANGE, Y_RANGE];\n    var step = STEP;\n    if (step === \"auto\") {\n        step = _.map(range, function(extent, i) {\n            return Perseus.Util.tickStepFromExtent(\n                    extent, dimensions[i]);\n        });\n    }\n    var gridConfig = _.map(range, function(extent, i) {\n        return Perseus.Util.gridDimensionConfig(\n                step[i],\n                extent,\n                dimensions[i]);\n    });\n    var scale = _.pluck(gridConfig, \"scale\");\n    xScale = scale[0];\n    yScale = scale[1];\n    var paddedRange = _.map(range, function(extent, i) {\n        var padding = 25 / scale[i];\n        return [extent[0], extent[1] + padding];\n    });\n    graphInit({\n        gridRange: range,\n        range: paddedRange,\n        scale: scale,\n        axisArrows: \"<->\",\n        labelFormat: function(s) {\n            return \"\\\\small{\" + s + \"}\";\n        },\n        gridStep: _.pluck(gridConfig, \"gridStep\"),\n        tickStep: _.pluck(gridConfig, \"tickStep\"),\n        labelStep: 1,\n        unityLabels: _.pluck(gridConfig, \"unityLabel\")\n    });\n    style({\n        clipRect: [[X_RANGE[0], Y_RANGE[0]],\n                [X_RANGE[1] - X_RANGE[0],\n                Y_RANGE[1] - Y_RANGE[0]]]\n    });\n\n    label([0, Y_RANGE[1]], \"y\", \"above\");\n    label([X_RANGE[1], 0], \"x\", \"right\");\n}\n\n"
  },
  {
    "id": "39_bar_plot",
    "title": "39. Bar Plot",
    "category": "General",
    "code": "\n\n/* Data to plot. Should be numbers indicating the height of each category. */\nvar data = [\n    [\"Group<br>A\", 5], //<br> splits the label over 2 lines\n    [\"Group<br>B\", 3],\n    [\"Group<br>C\", 9],\n    [\"Group<br>D\", 6]\n];\n\n/* y-parameters */\nvar yMin = 0;\nvar yMax = 10;\nvar yScale = 1;\n\n/* Graph styles */\nvar xLabel = \"X categories\";\nvar yLabel = \"Y values\";\nvar title = \"Graph title\";\n\n// Bar plots typically use light colors\nvar colors = [GREEN_B, PURPLE_B, TEAL_B, MAROON_B];\nvar outlines = [GREEN_E, PURPLE_E, TEAL_E, MAROON_E];\nvar tickHeight = 6;\nvar plotDimensions = [240, 180];\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n/* Setup the canvas                                       */\n\n// Calculate x-parameters\nvar numBins = _.size(data);\nvar barPad = 0.15;\nvar barWidth = 1 - 2 * barPad;\nvar barHalfWidth = barWidth / 2;\nvar dimX = numBins + 2 * barPad;\n\n// Calculuate additional y-parameters\nvar dimY = Math.ceil((yMax - yMin) / yScale) * yScale;\n\n// Calculate scale and range\nvar scale = _.map([dimX, dimY], function (dim, i) {\n    return plotDimensions[i] / dim;\n});\nvar padX = 20 / scale[0];\nvar padY = 20 / scale[1];\nvar padYTop = title ? padY * 3 : padY;\nvar range = [[-3 * padX, dimX], [-3.5 * padY, dimY + padYTop]];\n\n// Initialize graph\ninit({\n    range: range,\n    scale: scale\n});\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n\n\n/* Begin plotting. First, plot the axis ticks, then the bars, then the  */\n/* axes. This ensures proper layout on the z-axis.                      */\nvar labelStep=Perseus.Util.tickStepFromExtent([0,dimY],plotDimensions[1]);\nfor (var y = 0; y <= dimY; y += yScale) {\n    style({opacity: 1.0});\n    if(y%labelStep===0){\n        label(\n            [0, y],\n            roundToApprox(y, 2),\n            \"left\",\n            /* isTeX */ true /* for the \\approx symbol */\n        );\n    }\n    style({stroke: \"#000\", strokeWidth: 1, opacity: 0.3});\n    line([0, y], [dimX, y]);\n}\n\n// Plot each bar with its label\n_.each(data, function(item, i) {\n    var count = item[1];\n    var category = item[0];\n    var x = 0.5 + i + barPad;\n\n    // Cycle through colors\n    style({opacity: 1, strokeWidth: 2, stroke: outlines[i%colors.length], fill: colors[i%colors.length]});\n\n    // Plot bar\n    path([\n            [x - barHalfWidth, 0],\n            [x - barHalfWidth, count],\n            [x + barHalfWidth, count],\n            [x + barHalfWidth, 0]\n        ]);\n        \n    // Plot bar label (below axis)\n    var scaledTickHeight = tickHeight / scale[1];\n    style({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\n    line([x, -scaledTickHeight], [x, 0]);\n    label([x, 0], \"<center>\"+category+\"</center>\", \"below\", false);\n});\n\n\n// Add axes (after drawing boxes)\nstyle({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\nline([0, 0], [dimX, 0]);\nline([0, 0], [0, dimY]);\n\n// Add title label\nif (title) {\n    label([dimX / 2, dimY + padYTop * 0.9],\n        title,\n        \"below\", false,\n        {\"font-weight\": \"bold\", \"font-size\": \"16px\"});\n}\n\n// Add axis labels\nlabel([dimX / 2, -45 / scale[1]],\n    xLabel,\n    \"below\", false)\n    .css(\"font-weight\", \"bold\");\n\nlabel([-45 / scale[0], dimY / 2],\n    yLabel,\n    \"center\", false)\n    .css(\"font-weight\", \"bold\")\n    .css(\"transform\", \"rotate(-90deg)\");\n\n"
  },
  {
    "id": "40_shade_area_between_curves",
    "title": "40. Shade area between curves",
    "category": "General",
    "code": "// X and Y ranges of the graph\nvar X_RANGE = [-10, 10];\nvar Y_RANGE = [-10, 10];\n\n// var STEP = [<x tick step>, <y tick step>];\n// var STEP = [10, 25];\nvar STEP = \"auto\";\n\n// Width of the graph in pixels\n// Let's use 320 for \"normal\" graphs and 170 for \"small\" graphs.\n// If this is for the background of a widget (transformer, interactive graph, etc), use 400.\nvar SIZE = 320;\n\nvar xScale;\nvar yScale;\nsetup();\n//////////////////////////////////////////////////////////////\n\n\n\nvar fn1 = function(x) {\n    // Define first function here\n    return - 0.5 * x * x + 3.0 * x - 2.0;\n};\n\nvar fn2 = function(x) {\n    // Define second function here\n    return x * x * x - 2.5 * x * x + 4 * x - 1.0;\n};\n\n// Styling for first function\nstyle({\n    stroke: BLUE_D,\n    fill: \"none\",\n    strokeWidth: 3\n});\n\nplot(fn1, X_RANGE);\n\n// Styling for second function\nstyle({\n    stroke: RED_D,\n    fill: \"none\"\n});\n\nplot(fn2, X_RANGE);\n\nplot(fn1,\n    [-2, 4], // <-- x-range to shade\n    false, // Don't swap axes, because it doesn't work with shading between functions\n    true, //Do shade between functions\n    fn2,\n    // Styling for shaded region between functions\n    {\n        stroke: \"none\",\n        fill: BLUE_D,\n        fillOpacity: 0.3\n    }\n);\n\n\n//////////////////////////////////////////////////////////////\n// Setup grid, ticks, and labels and initialize graph.\nfunction setup() {\n    var dimensions = [SIZE, SIZE];\n    var range = [X_RANGE, Y_RANGE];\n    var step = STEP;\n    if (step === \"auto\") {\n        step = _.map(range, function(extent, i) {\n            return Perseus.Util.tickStepFromExtent(\n                    extent, dimensions[i]);\n        });\n    }\n    var gridConfig = _.map(range, function(extent, i) {\n        return Perseus.Util.gridDimensionConfig(\n                step[i],\n                extent,\n                dimensions[i]);\n    });\n    var scale = _.pluck(gridConfig, \"scale\");\n    xScale = scale[0];\n    yScale = scale[1];\n    var paddedRange = _.map(range, function(extent, i) {\n        var padding = 25 / scale[i];\n        return [extent[0], extent[1] + padding];\n    });\n    graphInit({\n        gridRange: range,\n        range: paddedRange,\n        scale: scale,\n        axisArrows: \"<->\",\n        labelFormat: function(s) {\n            return \"\\\\small{\" + s + \"}\";\n        },\n        gridStep: _.pluck(gridConfig, \"gridStep\"),\n        tickStep: _.pluck(gridConfig, \"tickStep\"),\n        labelStep: 1,\n        unityLabels: _.pluck(gridConfig, \"unityLabel\")\n    });\n    style({\n        clipRect: [[X_RANGE[0], Y_RANGE[0]],\n                [X_RANGE[1] - X_RANGE[0],\n                Y_RANGE[1] - Y_RANGE[0]]]\n    });\n\n    label([0, Y_RANGE[1]], \"y\", \"above\");\n    label([X_RANGE[1], 0], \"x\", \"right\");\n}\n\n"
  },
  {
    "id": "40a_shade_horizontal_area_between_curves",
    "title": "40a. Shade horizontal area between curves",
    "category": "General",
    "code": "// X and Y ranges of the graph\nvar X_RANGE = [-10, 10];\nvar Y_RANGE = [-10, 10];\n\n// var STEP = [<x tick step>, <y tick step>];\n// var STEP = [10, 25];\nvar STEP = \"auto\";\n\n// Width of the graph in pixels\n// Let's use 320 for \"normal\" graphs and 170 for \"small\" graphs.\n// If this is for the background of a widget (transformer, interactive graph, etc), use 400.\nvar SIZE = 320;\n\nvar xScale;\nvar yScale;\nsetup();\n//////////////////////////////////////////////////////////////\n\n\n\nvar fn1 = function(t) {\n    // Define first function here\n    return [- 0.5 * t * t + 3.0 * t - 2.0,t];\n};\n\nvar fn2 = function(t) {\n    // Define second function here\n    return [t * t * t - 2.5 * t * t + 4 * t - 1.0,t];\n};\n\n// Styling for first function\nstyle({\n    stroke: BLUE_D,\n    fill: \"none\",\n    strokeWidth: 3\n});\n\nplotParametric(fn1, Y_RANGE);\n\n// Styling for second function\nstyle({\n    stroke: RED_D,\n    fill: \"none\"\n});\n\nplotParametric(fn2, Y_RANGE);\n\nplotParametric(fn1,\n    [-2, 4], // <-- y-range to shade\n    true, //Do shade between functions\n    fn2,\n    // Styling for shaded region between functions\n    {\n        stroke: \"none\",\n        fill: BLUE_D,\n        fillOpacity: 0.3\n    }\n);\n\n\n//////////////////////////////////////////////////////////////\n// Setup grid, ticks, and labels and initialize graph.\nfunction setup() {\n    var dimensions = [SIZE, SIZE];\n    var range = [X_RANGE, Y_RANGE];\n    var step = STEP;\n    if (step === \"auto\") {\n        step = _.map(range, function(extent, i) {\n            return Perseus.Util.tickStepFromExtent(\n                    extent, dimensions[i]);\n        });\n    }\n    var gridConfig = _.map(range, function(extent, i) {\n        return Perseus.Util.gridDimensionConfig(\n                step[i],\n                extent,\n                dimensions[i]);\n    });\n    var scale = _.pluck(gridConfig, \"scale\");\n    xScale = scale[0];\n    yScale = scale[1];\n    var paddedRange = _.map(range, function(extent, i) {\n        var padding = 25 / scale[i];\n        return [extent[0], extent[1] + padding];\n    });\n    graphInit({\n        gridRange: range,\n        range: paddedRange,\n        scale: scale,\n        axisArrows: \"<->\",\n        labelFormat: function(s) {\n            return \"\\\\small{\" + s + \"}\";\n        },\n        gridStep: _.pluck(gridConfig, \"gridStep\"),\n        tickStep: _.pluck(gridConfig, \"tickStep\"),\n        labelStep: 1,\n        unityLabels: _.pluck(gridConfig, \"unityLabel\")\n    });\n    style({\n        clipRect: [[X_RANGE[0], Y_RANGE[0]],\n                [X_RANGE[1] - X_RANGE[0],\n                Y_RANGE[1] - Y_RANGE[0]]]\n    });\n\n    label([0, Y_RANGE[1]], \"y\", \"above\");\n    label([X_RANGE[1], 0], \"x\", \"right\");\n}\n\n"
  },
  {
    "id": "41_shade_area_bounded_by_polar_curve",
    "title": "41. Shade area bounded by polar curve",
    "category": "General",
    "code": "// radius of the graph\nvar R_MAX = 6;\n\n// var STEP = [<r tick step>, <theta tick step>];\nvar STEP = [1, PI/12];\n\n// whether (and how) to label things\nvar LABEL_R = true;\nvar LABEL_THETA = true;\nvar LABEL_DEGREES = false;  // ignored if LABEL_THETA is false\n\n// Width of the graph in pixels\nvar SIZE = 320;\n\nsetup();\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n\n\n// EXAMPLE 1: Shade part of a function\n\n// Define a function called fn1\nvar fn1 = function(theta) {\n    return 2 + 4 * cos(theta);\n};\n\n// Shade the inside of fn1 except for the part inside the\n// inner loop by first shading the entire thing, then\n// excluding the area from 2pi/3 to 4pi/3 where the\n// curve passes through the origin.\nshadePolar([\n    [\"include\", fn1, [0, 2*PI]],\n    [\"exclude\", fn1, [2*PI/3, 4*PI/3]]\n], BLUE_D);\n\n// Plot the function itself\nplotPolar(fn1, [0, 2*PI], {\n    stroke: BLUE_D,\n    strokeWidth: 3\n});\n\n\n// EXAMPLE 2: Shade between two functions\n\n// Define a function called fn2, the green circle\nvar fn2 = function(theta) {\n    return -4 * cos(theta);\n};\n\n// Define a function called fn3, the red circle\nvar fn3 = function(theta) {\n    return 2;\n};\n\n// Shade the area inside the green circle, except for\n// the area that's inside the red circle.\nshadePolar([\n    [\"include\", fn2, [0, 2*PI]],\n    [\"exclude\", fn3, [0, 2*PI]],\n], GREEN_D);\n\n// Plot the left circle\nplotPolar(fn2, [0, 2*PI], {\n    stroke: GREEN_D,\n    strokeWidth: 3\n});\n\n// Plot the left half of the right circle\nplotPolar(fn3, [PI/2, 3*PI/2], {\n    stroke: RED_D,\n    strokeWidth: 3\n});\n\n\n// END OF EXAMPLES\n// You probably don't want to modify anything below this line\n\n////////////////////////////////////////////////////////////////\n\nfunction shadePolar(functionList, color) {\n    // Raphael doesn't support masks since they aren't supported in VML,\n    // so this directly manipulates the SVG, breaking many abstractions in\n    // the process. :)\n    var svg = KhanUtil.currentGraph.raphael.canvas;\n\n    // Add a new SVG mask with a unique id\n    var maskId = (Math.random() * 1e20).toString(36);\n    var mask = document.createElementNS(\"http://www.w3.org/2000/svg\", \"mask\");\n    $(mask).attr(\"id\", maskId);\n    var defs = $(svg).find(\"defs\");\n    defs.append(mask);\n\n    _.each(functionList, function(fn) {\n        // We're making an alpha key, so areas to be filled should be white\n        // and areas that shouldn't be filled should be black.\n        var style = {\n            fill: fn[0] === \"include\" ? \"#fff\" : \"#000\",\n            stroke: \"none\"\n        };\n\n        // Plot the function over the specified range\n        var fnPath = plotPolar(fn[1], fn[2], style);\n\n        // We don't want to close the shape by just connecting the starting\n        // point to the ending point. E.g., we could be shading a wedge of a\n        // circle. So we always want to end at (0, 0). This hackily appends it:\n        var pole = scalePoint([0, 0]);\n        var lastPath = $(fnPath.items[fnPath.items.length - 1].node);\n        lastPath.attr(\"d\", lastPath.attr(\"d\") + \"L\" + pole[0] + \",\" + pole[1]);\n\n        // Extract the SVG elements we just added from the SVG and stick them\n        // in the mask\n        _.each(fnPath.items, function(item) {\n            $(mask).append(item.node);\n        });\n    });\n\n    // Draw a giant rectangle covering the entire canvas\n    var rectangle = KhanUtil.currentGraph.raphael.rect(0, 0,\n            $(svg).attr(\"width\"), $(svg).attr(\"height\"));\n\n    // Set the color of the giant rectangle to the right thing and apply\n    // the alpha mask we just created above.\n    $(rectangle.node).attr({\n        fill: color,\n        \"fill-opacity\": 0.3,\n        mask: \"url(#\" + maskId + \")\"\n    });\n}\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n// Setup grid, ticks, and labels and initialize graph.\nfunction setup() {\n    var dimensions = [SIZE, SIZE];\n    var range = [[-R_MAX, R_MAX], [-R_MAX, R_MAX]];\n\n    var gridConfig = _.map(range, function(extent, i) {\n        return Perseus.Util.gridDimensionConfig(\n                STEP[0],\n                extent,\n                dimensions[i]);\n    });\n    var scale = _.pluck(gridConfig, \"scale\");\n\n    var paddedRange = range;\n    if (LABEL_THETA) {\n        paddedRange = _.map(range, function(extent, i) {\n            var padding = 35 / scale[i];\n            return [extent[0] - padding, extent[1] + padding];\n        });\n    }\n\n    init({\n        range: paddedRange,\n        scale: scale\n    });\n    for (var r = STEP[0]; r <= R_MAX; r += STEP[0]) {\n        circle([0, 0], r, {\n            stroke: BLACK,\n            opacity: 0.1\n        });\n        if (LABEL_R && r < R_MAX) {\n            label([r, 0], \"\\\\small{\" + r + \"}\", \"below\");\n        }\n    }\n    for (var theta = 0; theta < 2*PI-1e-9; theta += STEP[1]) {\n        line([0, 0], [cos(theta) * R_MAX,\n            sin(theta) * R_MAX], {\n                stroke: BLACK,\n                opacity: 0.1\n            });\n            if (LABEL_THETA) {\n                var lbl = piFraction(theta, true);\n                if (LABEL_DEGREES) {\n                    lbl = round(theta * 180/PI) + \"^\\\\circ\";\n                }\n                label([cos(theta) * (R_MAX + 20/scale[0]),\n                    sin(theta) * (R_MAX + 20/scale[1])],\n                    \"\\\\small{\" + lbl + \"}\", \"center\");\n            }\n    }\n    graphInit({\n        grid: false,\n        gridRange: range,\n        range: paddedRange,\n        scale: scale,\n        axisArrows: \"<->\",\n        labelFormat: function(s) {\n            return \"\\\\small{\" + s + \"}\";\n        },\n        tickStep: STEP[0]\n    });\n    style({\n        clipRect: [[-R_MAX, -R_MAX],\n                [2 * R_MAX, 2 * R_MAX]],\n        \"plot-points\": 10000\n    });\n}\n"
  },
  {
    "id": "42_slope_field",
    "title": "42. Slope field",
    "category": "General",
    "code": "\n\nvar diffEq = function(x, y) {\n    // Define the differential equation here\n    return -x / y;\n};\n\n// Styling for slope field lines\nstyle({\n    stroke: BLUE_D,\n    fill: \"none\"\n});\n\n// How long should the lines of the slope field be?\nvar slopeLength = 0.5;\n// What's the step size of the slope field?\nvar xStep = 1;\nvar yStep = 1;\n\n// Plot the slope field\ndrawSlopeField(diffEq, X_RANGE, Y_RANGE, xStep, yStep, slopeLength);\n\n//////////////////////////////////////////////////////////////\nfunction drawSlopeField(fn, domain, range, xStep, yStep, slopeLength) {\n    for (var x = domain[0]; x <= domain[1]; x += xStep) {\n        for (var y = range[0]; y <= range[1]; y += yStep) {\n            var slope = fn(x, y);\n\n            // Convert slope into a normalized direction vector\n            var directionVector;\n            if (_.isFinite(slope)) {\n                directionVector = kvector.normalize([1, slope]);\n            } else if (slope === Number.POSITIVE_INFINITY) {\n                directionVector = [0, 1];\n            } else if (slope === Number.NEGATIVE_INFINITY) {\n                directionVector = [0, -1];\n            } else {\n                continue;\n            }\n\n            // Scale to slopeLength\n            var differenceVector = kvector.scale(directionVector, slopeLength / 2);\n\n            // Apply difference and plot\n            var middle = [x, y];\n            var start = kvector.subtract(middle, differenceVector);\n            var end = kvector.add(middle, differenceVector);\n            line(start, end);\n        }\n    }\n}\n\n\n"
  },
  {
    "id": "43_histogram",
    "title": "43. Histogram",
    "category": "General",
    "code": "\n\n/* Data to plot. Should be numbers indicating the height of each bucket. */\nvar data = [\n    5,\n    3,\n    9,\n    6\n];\n\n/* y-parameters */\nvar yMin = 0;\nvar yMax = 10;\nvar yScale = 1;\n\n/* bucket parameters */\nvar minBucket = 2;\nvar maxBucket = 10;\n\n/* Graph styles */\nvar xLabel = \"X values\";\nvar yLabel = \"Y values\";\n// Bar plots typically use light colors\nvar colors = [BLUE_C, RED_C, GREEN_C];\nvar tickHeight = 6;\nvar plotDimensions = [240,180];\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n/* Setup the canvas                                       */\n\n// Calculate x-parameters\nvar numBins = _.size(data);\nvar bucketSize = (maxBucket - minBucket) / numBins;\nvar barPad = 0.15;\nvar barWidth = 1;\nvar barHalfWidth = barWidth / 2;\nvar dimX = numBins + 2 * barPad;\n\n// Calculuate additional y-parameters\nvar dimY = Math.ceil((yMax - yMin) / yScale) * yScale;\n\n// Calculate scale and range\nvar scale = _.map([dimX, dimY], function (dim, i) {\n    return plotDimensions[i] / dim;\n});\nvar padX = 20 / scale[0];\nvar padY = 20 / scale[1];\nvar range = [[-3 * padX, dimX], [-3 * padY, dimY + padY]];\n\n// Initialize graph\ninit({\n    range: range,\n    scale: scale\n});\nvar labelStep=Perseus.Util.tickStepFromExtent([yMin,yMax],plotDimensions[1]);\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n\n\n/* Begin plotting. First, plot the axis ticks, then the bars, then the  */\n/* axes. This ensures proper layout on the z-axis.                      */\nfor (var y = 0; y <= dimY; y += yScale) {\n    style({opacity: 1.0});\n    if(y%labelStep===0){\n        label(\n            [0, y],\n            roundToApprox(y, 2),\n            \"left\",\n            /* isTeX */ true /* for the \\approx symbol */\n        );\n    }\n    style({stroke: \"#000\", strokeWidth: 1, opacity: 0.3});\n    line([0, y], [dimX, y]);\n}\n\n// Plot each bar with its label\n_.each(data, function(item, i) {\n    var count = item;\n    var x = 0.5 + i + barPad;\n\n    // Cycle through colors\n    style({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\n    var color = colors[i % colors.length];\n    style({stroke: \"none\", fill: color});\n\n    // Plot bar\n    path([\n            [x - barHalfWidth, 0],\n            [x - barHalfWidth, count],\n            [x + barHalfWidth, count],\n            [x + barHalfWidth, 0]\n        ]);\n});\n\n// Plot each bar with its label\n_.times(numBins + 1, function(i) {\n    var x = i + barPad;\n    var l = (i * bucketSize) + minBucket;\n\n    // Plot the label tick mark\n    style({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\n    var scaledTickHeight = tickHeight / scale[1];\n    line([x, -scaledTickHeight], [x, 0]);\n\n    // Draw the label\n    label([x, -0.1], l, \"below\", true);\n});\n\n// Add axes (after drawing boxes)\nstyle({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\nline([0, 0], [dimX, 0]);\nline([0, 0], [0, dimY]);\n\n// Add axis labels\nlabel([dimX / 2, -35 / scale[1]],\n    xLabel,\n    \"below\", false)\n    .css(\"font-weight\", \"bold\");\n\nlabel([-45 / scale[0], dimY / 2],\n    yLabel,\n    \"center\", false)\n    .css(\"font-weight\", \"bold\")\n    .css(\"transform\", \"rotate(-90deg)\");\n\n\n"
  },
  {
    "id": "44_segmented_bar_graph",
    "title": "44. Segmented bar graph",
    "category": "General",
    "code": "\n\n/* Data to plot. Should be pairs consisting of a category\nlabel and a list of values.  List of values\nshould add to 100, or whatever yMax happens to be*/\nvar data = [\n    ['X group<br>1', [20, 30, 10, 40]], //<br> splits the label over 2 lines\n    ['X group<br>2', [30, 60, 0, 10]],\n    ['X group<br>3', [40, 20, 20, 20]],\n];\n\n/* y-parameters */\nvar yMin = 0;\nvar yMax = 100;\nvar yScale = 20;\nvar usePercents = true;\n\n/* Graph styles */\nvar xLabel = \"X Label\";\nvar yLabel = \"Y Label\";\nvar title = \"Name of graph\";\nvar tickHeight = 6;\nvar plotDimensions = [240,180];\n\n/* Second category type information */\n// Length of both these lists should match length of \n// values in second coordinate of each data point\nvar colors = [\n    BLUE_E, \n    BLUE_D, \n    BLUE_C, \n    BLUE_B\n];\nvar YCategoryNames = [\n    \"Y group 1\",\n    \"Y group 2\",\n    \"Y group 3\",\n    \"Y group 4\"   \n];\nvar yCategoryLabelSpacing = 10;\nvar squareWidth = 15;\n\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n/* Setup the canvas                                       */\n\n_.each(data,function(item){\n    item[1].reverse();\n    });\nYCategoryNames.reverse();\n\n// Calculate x-parameters\nvar numBins = _.size(data);\nvar barPad = 0.15;\nvar barWidth = 1 - 2 * barPad;\nvar barHalfWidth = barWidth / 2;\nvar dimX = numBins + 2 * barPad;\n\n// Calculuate additional y-parameters\nvar dimY = Math.ceil((yMax - yMin) / yScale) * yScale;\n\n// Calculate scale and range\nvar scale = _.map([dimX, dimY], function (dim, i) {\n    return plotDimensions[i] / dim;\n});\nvar padX = 20 / scale[0];\nvar padY = 20 / scale[1];\nvar padYTop = title ? padY * 3 : padY;\nvar legendSpace = 120 / scale[1];\nvar range = [\n    [-3 * padX, dimX], \n    [-3 * padY - legendSpace, dimY + padYTop],\n];\n\n// Initialize graph\ninit({\n    range: range,\n    scale: scale\n});\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n\n\n/* Begin plotting. First, plot the axis ticks, then the bars, then the  */\n/* axes. This ensures proper layout on the z-axis.                      */\nfor (var y = 0; y <= dimY; y += yScale) {\n    style({opacity: 1.0});\n    if(usePercents){\n        var addOn = \"\\\\%\";\n    }else{\n        var addOn = \"\";\n    }\n    label(\n        [0, y],\n        roundToApprox(y, 2) + addOn,\n        \"left\",\n        /* isTeX */ true /* for the \\approx symbol */\n    );\n    style({stroke: \"#000\", strokeWidth: 1, opacity: 0.3});\n    line([0, y], [dimX, y]);\n}\n\n// Plot each bar with its label\n_.each(data, function(item, i) {\n    var category = item[0];\n    var values = item[1];\n    var x = 0.5 + i + barPad;\n\n    // Plot bar label (below axis)\n    var scaledTickHeight = tickHeight / scale[1];\n    style({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\n    line([x, -scaledTickHeight], [x, 0]);\n    label([x, 0], \"<center>\"+category+\"</center>\", \"below\", false);\n\n    // Plot bar\n    var lastY = 0;\n    for(var j = 0; j < values.length; j++){\n        var color = colors[j % colors.length];\n        var newY = lastY+values[j];\n        path([\n            [x - barHalfWidth, lastY],\n            [x - barHalfWidth, newY],\n            [x + barHalfWidth, newY],\n            [x + barHalfWidth, lastY]\n        ], {stroke: BLACK, strokeWidth: 1, fill: color});\n        lastY = newY;\n    }\n});\n\n// Add axes (after drawing boxes)\nstyle({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\nline([0, 0], [dimX, 0]);\nline([0, 0], [0, dimY]);\n\n// Add title label\nif (title) {\n    label([dimX / 2, dimY + padYTop * 0.9],\n        title,\n        \"below\", false,\n        {\"font-weight\": \"bold\", \"font-size\": \"16px\"});\n}\n\n// Add axis labels\nlabel([dimX / 2, -45 / scale[1]],\n    xLabel,\n    \"below\", false)\n    .css(\"font-weight\", \"bold\");\n\nlabel([-55 / scale[0], dimY / 2],\n    yLabel,\n    \"center\", false)\n    .css(\"font-weight\", \"bold\")\n    .css(\"transform\", \"rotate(-90deg)\");\n    \n    \n/* Add Legend */\nvar xStart = 0; // modify to shift legend right/left\nvar yStart = 0; // modify to shift legend up/down\n_.each(YCategoryNames, function(name, i){\n    var y = -legendSpace - (padY * 2) + yCategoryLabelSpacing * i;\n    var color = colors[i % colors.length];\n    drawPolygon({points:[\n            [xStart + 0, yStart + y + squareWidth / scale[1] / 2],\n            [xStart + squareWidth / scale[0], yStart + y + squareWidth / scale[1] / 2],\n            [xStart + squareWidth / scale[0], yStart + y - squareWidth / scale[1] / 2],\n            [xStart + 0, yStart + y - squareWidth / scale[1] / 2]\n        ],\n        stroke: BLACK,\n        strokeWidth: 1,\n        fill: color,\n        fillOpacity: 1,\n        angleLabels: []\n    });\n    label([xStart + squareWidth / scale[0], yStart + y], name, \"right\", false);\n});\n\n\n"
  },
  {
    "id": "45_side_by_side_bar_graph",
    "title": "45. Side-by-side bar graph",
    "category": "General",
    "code": "\n\n/* Data to plot. Should be pairs consisting of a category\nlabel and a list of values.  List of values\nshould add to 100, or whatever yMax happens to be*/\nvar data = [\n    ['X class<br>1', [20, 30, 10, 40]], //<br> splits the label over 2 lines\n    ['X class<br>2', [30, 60, 0, 10]],\n    ['X class<br>3', [40, 20, 20, 20]],\n];\n\n/* y-parameters */\nvar yMin = 0;\nvar yMax = 100;\nvar yScale = 20;\nvar usePercents = true;\n\n/* Graph styles */\nvar xLabel = \"X Label\";\nvar yLabel = \"Y Label\";\nvar title = \"Name of graph\";\nvar tickHeight = 6;\nvar plotDimensions = [240,180];\n\n/* Second category type information */\n// Bar plots typically use light colors\n// Length both these lists should match length of \n// values in second coordinate of each data point\nvar colors = [\n    PURPLE_E, \n    PURPLE_D, \n    PURPLE_C, \n    PURPLE_B\n];\nvar groupNames = [\n    \"Group 1\",\n    \"Group 2\",\n    \"Group 3\",\n    \"Group 4\",    \n];\nvar yCategoryLabelSpacing = 10;\nvar squareWidth = 15;\n\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n/* Setup the canvas                                       */\n\n// Calculate x-parameters\nvar numBins = _.size(data);\nvar barPad = 0.15;\nvar barWidth = 1 - 2 * barPad;\nvar barHalfWidth = barWidth / 2;\nvar dimX = numBins + 2 * barPad;\n\n// Calculuate additional y-parameters\nvar dimY = Math.ceil((yMax - yMin) / yScale) * yScale;\n\n// Calculate scale and range\nvar scale = _.map([dimX, dimY], function (dim, i) {\n    return plotDimensions[i] / dim;\n});\nvar padX = 20 / scale[0];\nvar padY = 20 / scale[1];\nvar padYTop = title ? padY * 3 : padY;\nvar legendSpace = 120 / scale[1];\nvar range = [\n    [-3 * padX, dimX], \n    [-3 * padY - legendSpace, dimY + padYTop],\n];\n\n// Initialize graph\ninit({\n    range: range,\n    scale: scale\n});\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n\n\n/* Begin plotting. First, plot the axis ticks, then the bars, then the  */\n/* axes. This ensures proper layout on the z-axis.                      */\nfor (var y = 0; y <= dimY; y += yScale) {\n    style({opacity: 1.0});\n    if(usePercents){\n        var addOn = \"\\\\%\";\n    }else{\n        var addOn = \"\";\n    }\n    label(\n        [0, y],\n        roundToApprox(y, 2) + addOn,\n        \"left\",\n        /* isTeX */ true /* for the \\approx symbol */\n    );\n    style({stroke: \"#000\", strokeWidth: 1, opacity: 0.3});\n    line([0, y], [dimX, y]);\n}\n\n// Plot each bar with its label\n_.each(data, function(item, i) {\n    var category = item[0];\n    var values = item[1];\n    var x = 0.5 + i + barPad;\n\n    // Plot bar label (below axis)\n    var scaledTickHeight = tickHeight / scale[1];\n    style({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\n    line([x, -scaledTickHeight], [x, 0]);\n    label([x, 0], \"<center>\"+category+\"</center>\", \"below\", false);\n\n    // Plot bar\n    var skinnyBarWidth = barWidth/data[0][1].length;\n    var xStart = x - barHalfWidth;\n    for(var j = 0; j < values.length; j++){\n        var color = colors[j % colors.length];\n        style({stroke: \"none\", fill: color});\n        path([\n            [xStart + skinnyBarWidth*j, 0],\n            [xStart + skinnyBarWidth*j, values[j]],\n            [xStart + skinnyBarWidth*(j+1), values[j]],\n            [xStart + skinnyBarWidth*(j+1), 0]\n        ], {stroke: BLACK, strokeWidth: 1});\n    }\n});\n\n// Add axes (after drawing boxes)\nstyle({stroke: \"#000\", strokeWidth: 2, opacity: 1.0});\nline([0, 0], [dimX, 0]);\nline([0, 0], [0, dimY]);\n\n// Add title label\nif (title) {\n    label([dimX / 2, dimY + padYTop * 0.9],\n        title,\n        \"below\", false,\n        {\"font-weight\": \"bold\", \"font-size\": \"16px\"});\n}\n\n// Add axis labels\nlabel([dimX / 2, -45 / scale[1]],\n    xLabel,\n    \"below\", false)\n    .css(\"font-weight\", \"bold\");\n\nlabel([-55 / scale[0], dimY / 2],\n    yLabel,\n    \"center\", false)\n    .css(\"font-weight\", \"bold\")\n    .css(\"transform\", \"rotate(-90deg)\");\n    \n    \n/* Add Legend */\nvar xLegend = 0; // modify to shift legend right/left\nvar yLegend = 0; // modify to shift legend up/down\ngroupNames.reverse();\n_.each(groupNames, function(name, i){\n    var y = -legendSpace - (padY*2) + yCategoryLabelSpacing*i;\n    color = colors[groupNames.length-(i % colors.length)-1];\n    drawPolygon({points: [\n        [xLegend + 0, yLegend + y + squareWidth / scale[1] / 2],\n        [xLegend + squareWidth / scale[0], yLegend + y + squareWidth / scale[1] / 2],\n        [xLegend + squareWidth / scale[0], yLegend + y - squareWidth / scale[1] / 2],\n        [xLegend + 0, yLegend + y - squareWidth / scale[1] / 2],\n    ],\n    stroke: BLACK,\n    strokeWidth: 1,\n    fill: color,\n    fillOpacity: 1\n    });\n    label([xLegend + squareWidth / scale[0], yLegend + y], name, \"right\", false);\n});\n\n\n"
  },
  {
    "id": "46_venn_diagram",
    "title": "46. Venn diagram",
    "category": "General",
    "code": "\n\ninit({\n    range: [[-5.1, 5.1], [-5.1, 6.4]], // coordinate system\n    scale: [30, 30] // pixes per unit\n    });\n\n// Background rectangle\ndrawPolygon({\n    points: [\n        [-5,-5],\n        [-5,6.3],\n        [5,6.3],\n        [5,-5]\n        ],\n    strokeWith: 2,\n    stroke: BLACK,\n    angleLabels: []\n});\n\n// Circles\ndrawCircle({\n    center: polar(2, 210),\n    radius: 2.8,\n    color: PURPLE_D,\n    fillOpacity: 0.4\n});\ndrawCircle({\n    center: polar(2, 90),\n    radius: 2.8,\n    color: GREEN_D,\n    fillOpacity: 0.4\n});\ndrawCircle({\n    center: polar(2, 330),\n    radius: 2.8,\n    color: BLUE_D,\n    fillOpacity: 0.4\n});\n\n// label the groups\nlabel(polar(5.5, 90), \"Group A\", \"center\", false, {color: GREEN_E, \"font-weight\": \"bold\"});\nline(polar(5.1, 90), polar(4.2, 90), {stroke: GREEN_E});\n\nlabel(polar(5.5, 230), \"Group B\", \"center\", false, {color: PURPLE_E, \"font-weight\": \"bold\"});\nline(polar(5.1, 230), polar(4.2, 230), {stroke: PURPLE_E});\n\nlabel(polar(5.5, 306), \"Group C\", \"center\", false, {color: BLUE_E, \"font-weight\": \"bold\"});\nline(polar(5.1, 310), polar(4.2, 310), {stroke: BLUE_E});\n\n// label the amounts\nlabel(polar(2.4, 330), \"27\");\nlabel(polar(2.4, 210), \"30\");\nlabel(polar(2.4, 90), \"19\");\nlabel(polar(0, 0), \"5\");\nlabel(polar(1.7, 30), \"10\");\nlabel(polar(1.7, 150), \"11\");\nlabel(polar(1.7, 270), \"7\");\nlabel(polar(4.3, 30), \"7\");\n\n"
  },
  {
    "id": "47_parallel_box_plots",
    "title": "47. Parallel box plots",
    "category": "General",
    "code": "\n\n// For an interactive example, see:\n// khan-exercises/exercises/creating_box_and_whisker_plots.html\n\nvar axisLabel = \"Axis label\";\nvar color = BLUE_D;\n\n/* Number line parameters */\nvar numberLineMin = 0;\nvar numberLineMax = 15;\nvar numberLineTickSize = 1;\n\nvar boxHeight = 0.8;\n\n/* Data distribution parameters */\nvar dataSets = [\n    {\n        name: \"Data Set A\",\n        color: BLUE_D,\n        q0: 1.5,\n        median: 5.5,\n        q1: 3,\n        q3: 9,\n        q4: 12,\n        outliers: [12.5, 13.7, 14.3]\n    }, {\n        name: \"Data Set B\",\n        color: PURPLE_D,\n        q0: 4.7,\n        q1: 6,\n        median: 6.5,\n        q3: 9,\n        q4: 10,\n        outliers: [0.7, 1.4, 11.3]\n    }, {\n        name: \"Data Set C\",\n        color: RED_D,\n        q0: 2.5,\n        q1: 4,\n        median: 6,\n        q3: 8,\n        q4: 11,\n        outliers: [13.4]\n    } \n];\n\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n/* Normalize points to the size of the canvas, and set up  */\n/* the canvas                                              */\nvar numberLineSpread = numberLineMax - numberLineMin;\nvar numberLineTickCount = numberLineSpread/numberLineTickSize;\nvar xrange = [ -0.5, numberLineTickCount + 0.5 ];\nvar yMin = axisLabel ? -4.5 : -3.5;\n\ninit({\n    range: [xrange, [ yMin, dataSets.length * 2.8 * boxHeight - boxHeight - 0.5]],\n    scale: _.min([30, Perseus.Util.scaleFromExtent(xrange, 320)])\n});\n/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - */\n\nvar normalize = function(number) {\n    return ((number - numberLineMin) / numberLineSpread) *\n        numberLineTickCount;\n};\nvar denormalize = function(position) {\n    return position * numberLineSpread / numberLineTickCount +\n        numberLineMin;\n};\n\n/* Draw the number line */\nvar labelStep=Perseus.Util.tickStepFromExtent([numberLineMin,numberLineMax],320);\nline([ 0, -2 ], [ numberLineTickCount, -2 ]);\nfor (tick = 0; tick <= numberLineTickCount; tick+=1) {\n    var tickValue = denormalize(tick);\n    line([ tick, -1.75 ], [ tick, -2.25 ]);\n    if((tickValue-numberLineMin)%labelStep===0){\n        label([ tick, -2.25 ], roundTo(1, tickValue), \"below\");\n    }\n}\n\nfor (var i = 0; i < dataSets.length; i++) {\n    var nq0 = normalize(dataSets[i].q0);\n    var nq1 = normalize(dataSets[i].q1);\n    var nmedian = normalize(dataSets[i].median);\n    var nq3 = normalize(dataSets[i].q3);\n    var nq4 = normalize(dataSets[i].q4);\n    \n    style({\n        strokeWidth: 2,\n        stroke: dataSets[i].color\n    });\n    \n    var y = boxHeight * 2.8 * i;\n    \n    // draw Q0\n    line([nq0, -0.2 + y], [nq0, 0.2 + y]);\n    line([nq0, 0 + y], [nq1, 0 + y]);\n    \n    // draw median\n    line([nmedian, boxHeight/2 + y], [nmedian, -boxHeight/2 + y]);\n    drawPolygon({\n        points: [\n            [nq1, -boxHeight/2 + y],\n            [nq1, boxHeight/2 + y],\n            [nq3, boxHeight/2 + y],\n            [nq3, -boxHeight/2 + y]\n            ],\n        stroke: dataSets[i].color,\n        strokeWidth: 2,\n        angleLabels: []\n    });\n    \n    // draw Q4\n    line([nq4, -0.2 + y], [nq4, 0.2 + y]);\n    line([nq3, 0 + y], [nq4, 0 + y]);\n    \n    // draw label\n    label([nmedian, y - boxHeight], dataSets[i].name, \"center\", false, {color: dataSets[i].color, \"font-weight\": \"bold\"});\n    \n    // draw outliers\n    var outliers = dataSets[i].outliers;\n    for (var j=0; j < outliers.length; j++) {\n        drawPoint({point: [outliers[j],0+y], color: dataSets[i].color});\n    }\n}\n\n// axis label\nif (axisLabel) {\n    label([numberLineTickCount/2, -3.4], axisLabel, \"below\", false, {\"font-weight\": \"bold\", \"font-size\": \"16px\"});\n}\n\n\n"
  }
